    public static string GenerateKey(){byte[] bytes=new byte[32];using(var rng=RandomNumberGenerator.Create())rng.GetBytes(bytes);return "mw_"+Convert.ToBase64String(bytes).TrimEnd('=').Replace('+','-').Replace('/','_');}
