,out toolIndex);StreamTool state;if(!tools.TryGetValue(toolIndex,out state)){state=new StreamTool{Block=nextBlock++,Id=Text(item,"id","tool_"+toolIndex),Name=""};tools[toolIndex]=state;}if(Text(item,"id")!="")state.Id=Text(item,"id");var function=Obj(Val(item,"function"));if(Text(function,"name")!="")state.Name+=Text(function,"name");if(!state.Started&&state.Name!=""){state.Started=true;await Event(output,"content_block_start",new{type="content_block_start",index=state.Block,content_block=new{type="tool_use",id=state.Id,name=state.Name,input=new Dictionary<string,object>()}},token);}string arguments=Text(function,"arguments");if(arguments!="")await Event(output,"content_block_delta",new{type="content_block_delta",index=state.Block,delta=new{type="input_json_delta",partial_json=arguments}},token);}string finish=Text(choice,"finish_reason");if(finish!="")stopReason=finish=="tool_calls"?"tool_use":finish=="length"?"max_tokens":"end_turn";}
        if(!started)await Event(output,"message_start",new{type="message_start",message=new{id=id,type="message",role="assistant",model=model,content=new object[0],stop_reason=(string)null,stop_sequence=(string)null,usage=new{input_tokens=inputTokens??0,output_tokens=0}}},token);if(textStarted)await Event(output,"content_block_stop",new{type="content_block_stop",index=textBlock},token);foreach(var tool in tools.Values)if(tool.Started)await Event(output,"content_block_stop",new{type="content_block_stop",index=tool.Block},token);await Event(output,"message_delta",new{type="message_delta",delta=new{stop_reason=stopReason,stop_sequence=(string)null},usage=new{output_tokens=outputTokens??0}},token);await Event(output,"message_stop",new{type="message_stop"},token);return Tuple.Create(inputTokens,outputTokens);}
    private static double? Number(Dictionary<string,object> value,string key){object raw=Val(value,key);double number;return raw!=null&&double.TryParse(Convert.ToString(raw),System.Globalization.NumberStyles.Any,System.Globalization.CultureInfo.InvariantCulture,out number)?(double?)number:null;}
    private static List<Dictionary<string,object>> AnthropicToChat(Dictionary<string,object> source){var messages=new List<Dictionary<string,object>>();object system=Val(source,"system");if(system!=null)messages.Add(Message("system",ContentText(system)));foreach(object raw in Items(Val(source,"messages"))){var item=Obj(raw);string role=Text(item,"role","user");var blocks=Items(Val(item,"content")).ToArray();if(Val(item,"content") is string){messages.Add(Message(role,Val(item,"content")));continue;}var text=new StringBuilder();var calls=new List<object>();foreach(object rawBlock in blocks){var block=Obj(rawBlock);string type=Text(block,"type");if(type=="text")text.Append(Text(block,"text"));else if(type=="tool_use")calls.Add(new{id=Text(block,"id"),type="function",function=new{name=Text(block,"name"),arguments=Json().Serialize(Val(block,"input")??new Dictionary<string,object>())}});else if(type=="tool_result"){if(text.Length>0){messages.Add(Message(role,text.ToString()));text.Clear();}messages.Add(new Dictionary<string,object>{{"role","tool"},{"tool_call_id",Text(block,"tool_use_id")},{"content",ContentText(Val(block,"content"))}});}}if(text.Length>0||calls.Count>0){var message=Message(role,text.ToString());if(calls.Count>0)message["tool_calls"]=calls;messages.Add(message);}}return messages;}
    private static List<Dictionary<string,object>> ResponsesToChat(Dictionary<string,object> source){var result=new List<Dictionary<string,object>>();if(Val(source,"instructions")!=null)result.Add(Message("system",Val(source,"instructions")));object input=Val(source,"input");if(input is string){result.Add(Message("user",input));return result;}foreach(object raw in Items(input)){var item=Obj(raw);string type=Text(item,"type","message");if(type=="function_call_output"){result.Add(new Dictionary<string,object>{{"role","tool"},{"tool_call_id",Text(item,"call_id")},{"content",Text(item,"output")}});continue;}if(type=="function_call"){result.Add(new Dictionary<string,object>{{"role","assistant"},{"content",""},{"tool_calls",new[]{new{id=Text(item,"call_id",Text(item,"id")),type="function",function=new{name=Text(item,"name"),arguments=Text(item,"arguments","{}")}}}}});continue;}string role=Text(item,"role","user");var content=Val(item,"content");result.Add(Message(role,ContentText(content)));}return result;}
    private static Dictionary<string,object> ChatRequest(Dictionary<string,object> source,string sourcePath,string model){var result=new Dictionary<string,object>{{"model",model}};if(sourcePath=="/messages"){result["messages"]=AnthropicToChat(source);if(Val(source,"max_tokens")!=null)result["max_tokens"]=Val(source,"max_tokens");if(Val(source,"temperature")!=null)result["temperature"]=Val(source,"temperature");if(Val(source,"top_p")!=null)result["top_p"]=Val(source,"top_p");if(Val(source,"stop_sequences")!=null)result["stop"]=Val(source,"stop_sequences");var tools=Items(Val(source,"tools")).Select(raw=>{var tool=Obj(raw);return (object)new{type="function",function=new{name=Text(tool,"name"),description=Text(tool,"description"),parameters=Val(tool,"input_schema")??new Dictionary<string,object>()}};}).ToArray();if(tools.Length>0)result["tools"]=tools;object choice=Val(source,"tool_choice");if(choice!=null){var pick=Obj(choice);string type=Text(pick,"type");result["tool_choice"]=type=="tool"?(object)new{type="function",function=new{name=Text(pick,"name")}}:type=="any"?"required":"auto";}}
        else if(sourcePath=="/responses"){result["messages"]=ResponsesToChat(source);if(Val(source,"max_output_tokens")!=null)result["max_tokens"]=Val(source,"max_output_tokens");if(Val(source,"temperature")!=null)result["temperature"]=Val(source,"temperature");if(Val(source,"top_p")!=null)result["top_p"]=Val(source,"top_p");if(Val(source,"stream")!=null)result["stream"]=Val(source,"stream");var tools=Items(Val(source,"tools")).Select(raw=>{var tool=Obj(raw);return (object)new{type="function",function=new{name=Text(tool,"name"),description=Text(tool,"description"),parameters=Val(tool,"parameters")??new Dictionary<string,object>()}};}).ToArray();if(tools.Length>0)result["tools"]=tools;}
        else {foreach(var pair in source)result[pair.Key]=pair.Value;result["model"]=model;}
        if(Val(source,"stream")!=null)result["stream"]=Val(source,"stream");if(Convert.ToBoolean(Val(result,"stream")??false)){var options=Obj(Val(result,"stream_options"));options["include_usage"]=true;result["stream_options"]=options;}return result;}
    private static Dictionary<string,object> ChatToMessages(Dictionary<string,object> chat){var choice=Items(Val(chat,"choices")).Select(Obj).FirstOrDefault()??new Dictionary<string,object>();var message=Obj(Val(choice,"message"));var blocks=new List<object>();string content=ContentText(Val(message,"content"));if(content.Length>0)blocks.Add(new{type="text",text=content});foreach(object raw in Items(Val(message,"tool_calls"))){var call=Obj(raw);var fn=Obj(Val(call,"function"));object input;try{input=Json().DeserializeObject(Text(fn,"arguments","{}"));}catch{input=new Dictionary<string,object>();}blocks.Add(new{type="tool_use",id=Text(call,"id"),name=Text(fn,"name"),input=input});}var usage=Obj(Val(chat,"usage"));string finish=Text(choice,"finish_reason");return new Dictionary<string,object>{{"id",Text(chat,"id","msg_proxy")},{"type","message"},{"role","assistant"},{"model",Text(chat,"model")},{"content",blocks},{"stop_reason",finish=="tool_calls"?"tool_use":finish=="length"?"max_tokens":"end_turn"},{"stop_sequence",null},{"usage",new{input_tokens=Val(usage,"prompt_tokens")??0,output_tokens=Val(usage,"completion_tokens")??0}}};}
    private static Dictionary<string,object> ChatToResponses(Dictionary<string,object> chat){var choice=Items(Val(chat,"choices")).Select(Obj).FirstOrDefault()??new Dictionary<string,object>();var message=Obj(Val(choice,"message"));var output=new List<object>();string text=ContentText(Val(message,"content"));if(text.Length>0)output.Add(new{ id="msg_"+Text(chat,"id","proxy"),type="message",role="assistant",status="completed",content=new[]{new{type="output_text",text=text,annotations=new object[0]}}});foreach(object raw in Items(Val(message,"tool_calls"))){var call=Obj(raw);var fn=Obj(Val(call,"function"));output.Add(new{id=Text(call,"id"),type="function_call",call_id=Text(call,"id"),name=Text(fn,"name"),arguments=Text(fn,"arguments","{}"),status="completed"});}var usage=Obj(Val(chat,"usage"));return new Dictionary<string,object>{{"id","resp_"+Text(chat,"id","proxy")},{"object","response"},{"status","completed"},{"model",Text(chat,"model")},{"output",output},{"output_text",text},{"usage",new{input_tokens=Val(usage,"prompt_tokens")??0,output_tokens=Val(usage,"completion_tokens")??0,total_tokens=Val(usage,"total_tokens")??0}}};}
    public static bool WantsStream(byte[] bytes){try{return Convert.ToBoolean(Val(Obj(Json().DeserializeObject(Encoding.UTF8.GetString(bytes))),"stream")??false);}catch{return false;}}
    public static byte[] ConvertRequest(byte[] bytes,string sourcePath,string targetPath,string model,bool bufferStream){var source=Obj(Json().DeserializeObject(Encoding.UTF8.GetString(bytes)));var chat=ChatRequest(source,sourcePath,model);if(bufferStream)chat["stream"]=false;if(targetPath=="/chat/completions")return Encoding.UTF8.GetBytes(Json().Serialize(chat));if(targetPath=="/messages"){var messages=Items(Val(chat,"messages")).Select(Obj).Where(m=>Text(m,"role")!="system").Select(m=>{string role=Text(m,"role");if(role=="tool")return (object)new Dictionary<string,object>{{"role","user"},{"content",new[]{new{type="tool_result",tool_use_id=Text(m,"tool_call_id"),content=Val(m,"content")}}}};var value=new Dictionary<string,object>(m);var content=new List<object>();string text=ContentText(Val(value,"content"));if(text.Length>0)content.Add(new{type="text",text=text});foreach(object raw in Items(Val(value,"tool_calls"))){var call=Obj(raw);var fn=Obj(Val(call,"function"));object input;try{input=Json().DeserializeObject(Text(fn,"arguments","{}"));}catch{input=new Dictionary<string,object>();}content.Add(new{type="tool_use",id=Text(call,"id"),name=Text(fn,"name"),input=input});}if(content.Count>0)value["content"]=content;value.Remove("tool_calls");return (object)value;}).ToArray();var payload=new Dictionary<string,object>{{"model",model},{"messages",messages},{"max_tokens",Val(chat,"max_tokens")??Val(source,"max_output_tokens")??1024}};var system=Items(Val(chat,"messages")).Select(Obj).FirstOrDefault(m=>Text(m,"role")=="system");if(system!=null)payload["system"]=Val(system,"content");if(Val(chat,"temperature")!=null)payload["temperature"]=Val(chat,"temperature");if(Val(chat,"top_p")!=null)payload["top_p"]=Val(chat,"top_p");if(Val(chat,"stream")!=null)payload["stream"]=Val(chat,"stream");var tools=Items(Val(chat,"tools")).Select(raw=>{var tool=Obj(raw);var fn=Obj(Val(tool,"function"));return (object)new{name=Text(fn,"name"),description=Text(fn,"description"),input_schema=Val(fn,"parameters")??new Dictionary<string,object>()};}).ToArray();if(tools.Length>0)payload["tools"]=tools;return Encoding.UTF8.GetBytes(Json().Serialize(payload));}if(targetPath=="/responses"){var input=new List<object>();string instructions="";foreach(object raw in Items(Val(chat,"messages"))){var item=Obj(raw);string role=Text(item,"role");if(role=="system"){instructions=ContentText(Val(item,"content"));continue;}if(role=="tool"){input.Add(new{type="function_call_output",call_id=Text(item,"tool_call_id"),output=ContentText(Val(item,"content"))});continue;}foreach(object callRaw in Items(Val(item,"tool_calls"))){var call=Obj(callRaw);var fn=Obj(Val(call,"function"));input.Add(new{type="function_call",call_id=Text(call,"id"),name=Text(fn,"name"),arguments=Text(fn,"arguments","{}")});}input.Add(new{type="message",role=role,content=new[]{new{type=role=="assistant"?"output_text":"input_text",text=ContentText(Val(item,"content"))}}});}var payload=new Dictionary<string,object>{{"model",model},{"input",input}};if(instructions!="")payload["instructions"]=instructions;if(Val(chat,"max_tokens")!=null)payload["max_output_tokens"]=Val(chat,"max_tokens");if(Val(chat,"temperature")!=null)payload["temperature"]=Val(chat,"temperature");if(Val(chat,"top_p")!=null)payload["top_p"]=Val(chat,"top_p");var tools=Items(Val(chat,"tools")).Select(raw=>{var tool=Obj(raw);var fn=Obj(Val(tool,"function"));return (object)new{type="function",name=Text(fn,"name"),description=Text(fn,"description"),parameters=Val(fn,"parameters")??new Dictionary<string,object>()};}).ToArray();if(tools.Length>0)payload["tools"]=tools;return Encoding.UTF8.GetBytes(Json().Serialize(payload));}return bytes;}
    private static Dictionary<string,object> MessagesToChat(Dictionary<string,object> message){var blocks=Items(Val(message,"content")).Select(Obj).ToArray();var text=string.Join("",blocks.Where(b=>Text(b,"type")=="text").Select(b=>Text(b,"text")));var calls=blocks.Where(b=>Text(b,"type")=="tool_use").Select(b=>(object)new{id=Text(b,"id"),type="function",function=new{name=Text(b,"name"),arguments=Json().Serialize(Val(b,"input")??new Dictionary<string,object>())}}).ToArray();var usage=Obj(Val(message,"usage"));return new Dictionary<string,object>{{"id",Text(message,"id","chatcmpl_proxy")},{"object","chat.completion"},{"model",Text(message,"model")},{"choices",new[]{new{index=0,message=new{role="assistant",content=text,tool_calls=calls.Length==0?null:calls},finish_reason=calls.Length>0?"tool_calls":Text(message,"stop_reason")=="max_tokens"?"length":"stop"}}},{"usage",new{prompt_tokens=Val(usage,"input_tokens")??0,completion_tokens=Val(usage,"output_tokens")??0,total_tokens=(Convert.ToInt32(Val(usage,"input_tokens")??0)+Convert.ToInt32(Val(usage,"output_tokens")??0))}}};}
    private static Dictionary<string,object> ResponsesToChatResponse(Dictionary<string,object> response){var output=new List<object>();var calls=new List<object>();foreach(object raw in Items(Val(response,"output"))){var item=Obj(raw);if(Text(item,"type")=="function_call"){calls.Add(new{id=Text(item,"call_id",Text(item,"id")),type="function",function=new{name=Text(item,"name"),arguments=Text(item,"arguments","{}")}});continue;}output.AddRange(Items(Val(item,"content")).Select(Obj).Where(b=>Text(b,"type")=="output_text").Select(b=>(object)new{type="text",text=Text(b,"text")}));}string text=string.Join("",output.Select(x=>Text(Obj(x),"text")));var usage=Obj(Val(response,"usage"));return new Dictionary<string,object>{{"id",Text(response,"id","chatcmpl_proxy")},{"object","chat.completion"},{"model",Text(response,"model")},{"choices",new[]{new{index=0,message=new{role="assistant",content=text,tool_calls=calls.Count==0?null:calls.ToArray()},finish_reason=calls.Count>0?"tool_calls":"stop"}}},{"usage",new{prompt_tokens=Val(usage,"input_tokens")??0,completion_tokens=Val(usage,"output_tokens")??0,total_tokens=Val(usage,"total_tokens")??0}}};}
    public static byte[] ConvertResponse(byte[] bytes,string sourcePath,string targetPath){var source=Obj(Json().DeserializeObject(Encoding.UTF8.GetString(bytes)));var chat=sourcePath=="/messages"?MessagesToChat(source):sourcePath=="/responses"?ResponsesToChatResponse(source):source;object value=targetPath=="/messages"?ChatToMessages(chat):targetPath=="/responses"?ChatToResponses(chat):chat;return Encoding.UTF8.GetBytes(Json().Serialize(value));}
    private static byte[] ChatToEventStream(Dictionary<string,object> value){var frames=new StringBuilder();var choice=Items(Val(value,"choices")).Select(Obj).FirstOrDefault()??new Dictionary<string,object>();var message=Obj(Val(choice,"message"));string id=Text(value,"id","chatcmpl_proxy"),model=Text(value,"model"),text=ContentText(Val(message,"content"));long created=DateTimeOffset.UtcNow.ToUnixTimeSeconds();frames.Append("data: ").Append(Json().Serialize(new{id=id,@object="chat.completion.chunk",created=created,model=model,choices=new[]{new{index=0,delta=new{role="assistant"},finish_reason=(string)null}}})).Append("\n\n");if(text.Length>0)frames.Append("data: ").Append(Json().Serialize(new{id=id,@object="chat.completion.chunk",created=created,model=model,choices=new[]{new{index=0,delta=new{content=text},finish_reason=(string)null}}})).Append("\n\n");int index=0;foreach(object raw in Items(Val(message,"tool_calls"))){var call=Obj(raw);var fn=Obj(Val(call,"function"));frames.Append("data: ").Append(Json().Serialize(new{id=id,@object="chat.completion.chunk",created=created,model=model,choices=new[]{new{index=0,delta=new{tool_calls=new[]{new{index=index,id=Text(call,"id"),type="function",function=new{name=Text(fn,"name"),arguments=Text(fn,"arguments","{}")}}}},finish_reason=(string)null}}})).Append("\n\n");index++;}string finish=Items(Val(message,"tool_calls")).Any()?"tool_calls":Text(choice,"finish_reason","stop");frames.Append("data: ").Append(Json().Serialize(new{id=id,@object="chat.completion.chunk",created=created,model=model,choices=new[]{new{index=0,delta=new{},finish_reason=finish}}})).Append("\n\n");var usage=Val(value,"usage");if(usage!=null)frames.Append("data: ").Append(Json().Serialize(new{id=id,@object="chat.completion.chunk",created=created,model=model,choices=new object[0],usage=usage})).Append("\n\n");frames.Append("data: [DONE]\n\n");return Encoding.UTF8.GetBytes(frames.ToString());}
    public static byte[] ToEventStream(byte[] json,string targetPath){var value=Obj(Json().DeserializeObject(Encoding.UTF8.GetString(json)));var frames=new StringBuilder();if(targetPath=="/messages"){var usage=Obj(Val(value,"usage"));string id=Text(value,"id","msg_proxy");frames.Append("event: message_start\ndata: ").Append(Json().Serialize(new{type="message_start",message=new{id=id,type="message",role="assistant",model=Text(value,"model"),content=new object[0],stop_reason=(string)null,stop_sequence=(string)null,usage=new{input_tokens=Val(usage,"input_tokens")??0,output_tokens=0}}})).Append("\n\n");int index=0;foreach(object raw in Items(Val(value,"content"))){var block=Obj(raw);string type=Text(block,"type");frames.Append("event: content_block_start\ndata: ").Append(Json().Serialize(new{type="content_block_start",index=index,content_block=block})).Append("\n\n");if(type=="text")frames.Append("event: content_block_delta\ndata: ").Append(Json().Serialize(new{type="content_block_delta",index=index,delta=new{type="text_delta",text=Text(block,"text")}})).Append("\n\n");else if(type=="tool_use")frames.Append("event: content_block_delta\ndata: ").Append(Json().Serialize(new{type="content_block_delta",index=index,delta=new{type="input_json_delta",partial_json=Json().Serialize(Val(block,"input")??new Dictionary<string,object>())}})).Append("\n\n");frames.Append("event: content_block_stop\ndata: ").Append(Json().Serialize(new{type="content_block_stop",index=index})).Append("\n\n");index++;}frames.Append("event: message_delta\ndata: ").Append(Json().Serialize(new{type="message_delta",delta=new{stop_reason=Text(value,"stop_reason","end_turn"),stop_sequence=(string)null},usage=new{output_tokens=Val(usage,"output_tokens")??0}})).Append("\n\n");frames.Append("event: message_stop\ndata: {\"type\":\"message_stop\"}\n\n");return Encoding.UTF8.GetBytes(frames.ToString());}
        if(targetPath=="/chat/completions")return ChatToEventStream(value);
        var choice=Items(Val(value,"choices")).Select(Obj).FirstOrDefault()??new Dictionary<string,object>();var message=Obj(Val(choice,"message"));string completionId=Text(value,"id","chatcmpl_proxy"),model=Text(value,"model");string text=ContentText(Val(message,"content"));
        if(targetPath=="/responses"){string id=Text(value,"id","resp_proxy");frames.Append("event: response.created\ndata: ").Append(Json().Serialize(new{type="response.created",response=new{id=id,@object="response",status="in_progress",output=new object[0]}})).Append("\n\n");if(text.Length>0){string itemId="msg_"+id;frames.Append("event: response.output_item.added\ndata: ").Append(Json().Serialize(new{type="response.output_item.added",output_index=0,item=new{id=itemId,type="message",role="assistant",status="in_progress",content=new object[0]}})).Append("\n\n");frames.Append("event: response.content_part.added\ndata: ").Append(Json().Serialize(new{type="response.content_part.added",item_id=itemId,output_index=0,content_index=0,part=new{type="output_text",text="",annotations=new object[0]}})).Append("\n\n");frames.Append("event: response.output_text.delta\ndata: ").Append(Json().Serialize(new{type="response.output_text.delta",item_id=itemId,output_index=0,content_index=0,delta=text})).Append("\n\n");frames.Append("event: response.output_text.done\ndata: ").Append(Json().Serialize(new{type="response.output_text.done",item_id=itemId,output_index=0,content_index=0,text=text})).Append("\n\n");frames.Append("event: response.content_part.done\ndata: ").Append(Json().Serialize(new{type="response.content_part.done",item_id=itemId,output_index=0,content_index=0,part=new{type="output_text",text=text,annotations=new object[0]}})).Append("\n\n");frames.Append("event: response.output_item.done\ndata: ").Append(Json().Serialize(new{type="response.output_item.done",output_index=0,item=new{id=itemId,type="message",role="assistant",status="completed",content=new[]{new{type="output_text",text=text,annotations=new object[0]}}}})).Append("\n\n");}frames.Append("event: response.completed\ndata: ").Append(Json().Serialize(new{type="response.completed",response=value})).Append("\n\n");return Encoding.UTF8.GetBytes(frames.ToString());}
